import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;
import io.vavr.control.Try;
import java.time.Duration;
import java.util.function.Supplier;

public class PaymentServiceClient {

    private final CircuitBreaker circuitBreaker;

    public PaymentServiceClient() {
        CircuitBreakerConfig config = CircuitBreakerConfig.custom()
            .failureRateThreshold(50.0)
            .slowCallRateThreshold(75.0)
            .slowCallDurationThreshold(Duration.ofMillis(200))
            .slidingWindowType(CircuitBreakerConfig.SlidingWindowType.COUNT_BASED)
            .slidingWindowSize(10)
            .minimumNumberOfCalls(5)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .permittedNumberOfCallsInHalfOpenState(3)
            .build();

        CircuitBreakerRegistry registry = CircuitBreakerRegistry.of(config);
        this.circuitBreaker = registry.circuitBreaker("paymentService");
    }

    public String processPayment(String payload) {
        Supplier<String> supplier = CircuitBreaker.decorateSupplier(
            circuitBreaker, 
            () -> callThirdPartyGateway(payload)
        );

        Try<String> result = Try.of(supplier::get)
            .recover(throwable -> fallbackPayment(payload, throwable));

        return result.get();
    }

    private String callThirdPartyGateway(String payload) {
        // Remote network call execution
        return "SUCCESS";
    }

    private String fallbackPayment(String payload, Throwable t) {
        return "FALLBACK_QUEUED";
    }
}
